/* Meetingnézet: csak forrásból igazolható ajánlatok, időszak szerint külön. */
(()=>{'use strict';let courses='2',channel='',mode='listed';const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=x=>typeof x==='number'&&Number.isFinite(x)?new Intl.NumberFormat('hu-HU').format(x)+' Ft':'Nem igazolt';const url=x=>/^https?:\/\//i.test(x||'')?`<a href="${e(x)}" target="_blank" rel="noopener">Forrás ↗</a>`:'Forrás nem ismert';const rowData=data=>(data['Napi menü árak']||[]).slice(1).filter(r=>r[0]).map(r=>({id:r[0],name:r[2],type:r[4],courses:r[5],channel:r[6]||'Nem egyértelmű',listed:typeof r[7]==='number'?r[7]:null,pay:r[6]==='Helyben'&&typeof r[10]==='number'?r[10]:null,box:r[11],dates:r[13]&&r[14]?`${r[13]} – ${r[14]}`:'Érvényesség nem ismert',checked:r[15],source:r[16],status:r[17],notes:r[19],charge:r[9]}));function novRows(data){return (data['Étlap 2026-11-09']||[]).slice(1).filter(r=>r[1]==='napi/heti menü'&&(/^[23] fogásos heti menü/i.test(String(r[2]))||/^[AC]\/([BD]) menü választott levessel/i.test(String(r[2])))&&typeof r[3]==='number'&&r[7]).map((r,i)=>({id:'nov-'+i,name:r[0],type:r[2],courses:/^3 fogás/i.test(r[2])?3:2,channel:'Nem egyértelmű',listed:r[3],pay:null,box:/Skorpió/.test(r[0])?100:null,dates:r[7],checked:r[6],source:r[5],status:'Korábbi gyűjtés; forrásellenőrzés szükséges',notes:r[8],charge:r[4],nov:true}))}function offers(data){return [...rowData(data),...novRows(data)]}const header=(tag,h,p)=>`<div class="eyebrow">${tag}</div><h1>${h}</h1><p class="section-intro">${p}</p>`;function overview(data,snapshot){let a=offers(data).filter(x=>x.courses===2&&x.listed!==null);let first=a.filter(x=>x.dates.includes('2026-11-09'));return header('ELEFÁNT · MEETINGANYAG','Mit látunk a veszprémi éttermeknél?','Árak, kínálat és versenytársak az újranyitásról szóló közös beszélgetéshez.')+`<div class="meeting-notice">Kutatási pillanatkép · utolsó adatimport: ${e(snapshot.imported_at||'nem ismert')} · az árak a feltüntetett időszakra vonatkoznak</div><div class="meeting-tiles"><article><span>01 · EBÉDMENÜ</span><h2>Mennyibe kerül máshol egy kétfogásos ebéd?</h2><p>${first.length?`A november 9-i gyűjtésben ${first.length} kétfogásos ajánlat található; a csatornát és a szervizdíjat még ellenőrizni kell.`:'Több történeti menüajánlatot rögzítettünk, eltérő időszakokból.'}</p><a href="#" data-go="2">Ebédmenük megtekintése →</a></article><article><span>02 · KÖZELBEN</span><h2>Kiket érdemes figyelni?</h2><p>A Chill az Óváros téren van, az Oliva is a történelmi belvárosban. A legfontosabb összehasonlítást a meetingen érdemes közösen kiválasztani.</p><a href="#" data-go="4">Versenytársak →</a></article><article><span>03 · KISZÁLLÍTÁS</span><h2>Mennyivel mások az online árak?</h2><p>Az összevetett fogásoknál külön látható a referencia és a Wolt-ár. Az adag és a csatorna nem minden esetben azonos.</p><a href="#" data-go="3">Árak és kalkulátor →</a></article><article><span>04 · SAJÁT ADATOK</span><h2>Mi kell még a döntéshez?</h2><p>Saját receptköltség, adagméret, eladások, platformjutalék és konyhai kapacitás nélkül nem tudjuk megmondani, mennyi az optimális ár.</p><a href="#" data-go="6">Kutatási háttér →</a></article></div><section class="panel"><h2>Mit beszéljünk meg Zsolttal és a séffel?</h2><div class="decision-list"><article><b>1. Ebédmenü</b><p>Milyen kétfogásos ajánlat fér bele a kívánt árszintbe? <span>A receptköltség és az adag még hiányzik.</span></p></article><article><b>2. Az új étlap</b><p>Milyen fogások illenek az új bistróhoz? <span>A régi Elefánt-étlap csak történeti kiindulópont.</span></p></article><article><b>3. Kiszállítás</b><p>Mit érdemes kiszállítani és milyen áron? <span>A valós jutalék és csomagolási költség még kell.</span></p></article><article><b>4. Nyitás</b><p>Mit, mikor és kinek kell előkészítenie? <span>A dátum, a séf és a tulajdonos jóváhagyása szükséges.</span></p></article></div></section><p class="muted">A Google Sheet nem kapcsolódik automatikusan ehhez a változathoz. A forrásban megfigyelt ár nem feltétlenül érvényes ma.</p>`}function lunch(data){let all=offers(data),seen=all.filter(x=>String(x.courses)===courses&&(!channel||x.channel===channel));let ranked=seen.filter(x=>x.listed!==null).sort((a,b)=>(a[mode]??Infinity)-(b[mode]??Infinity));let max=Math.max(1,...ranked.map(x=>x[mode]||0));let unknown=all.filter(x=>!x.courses||x.listed===null);return header('EBÉDMENÜ','Mennyibe kerül máshol az ebéd?','Összehasonlítható csomagok, a megfigyelés dátumával. A külön árazott levesből és főételből nem számolunk csomagot.')+`<div class="form meeting-filters"><label>Fogások száma<select id="meet-courses"><option value="2" ${courses==='2'?'selected':''}>Kétfogásos</option><option value="3" ${courses==='3'?'selected':''}>Háromfogásos</option></select></label><label>Fogyasztás módja<select id="meet-channel"><option value="">Minden csatorna</option>${['Helyben','Elvitel','Nem egyértelmű'].map(x=>`<option ${channel===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Rendezés<select id="meet-mode"><option value="listed" ${mode==='listed'?'selected':''}>Kiírt ár</option><option value="pay" ${mode==='pay'?'selected':''}>Ellenőrzött szervizdíjas helyszíni ár</option></select></label><button class="small-btn" id="meet-reset">Szűrők törlése</button></div><p class="muted">${ranked.length} ajánlat · különböző időszakok és csatornák · azonos étterem több időszakban is szerepelhet</p><div class="warning">A kiírt árak nem feltétlenül tartalmaznak minden díjat. A végösszeget csak ismert helyszíni szervizdíj esetén mutatjuk; elvitelnél a dobozok száma és a teljes összeg nem igazolt.</div><div class="offer-list">${ranked.map(x=>`<article class="offer"><div class="offer-head"><div><h3>${e(x.name)}</h3><p>${e(x.type)} · ${e(x.channel)}</p></div><strong>${money(mode==='listed'?x.listed:x.pay)}</strong></div><div class="offer-track"><div style="width:${x[mode]?Math.max(1,100*x[mode]/max):0}%"></div></div><p><b>Kiírt:</b> ${money(x.listed)} · <b>Szervizdíjas helyszíni ár:</b> ${money(x.pay)}</p><p><b>Ajánlat:</b> ${e(x.dates)} · <b>Ellenőrzés:</b> ${e(x.checked||'nem ismert')}</p><details><summary>Feltételek, díjak és forrás</summary><p>Szervizdíj: ${e(x.charge||'nem igazolt')} · Doboz: ${x.box!=null?money(x.box)+'/db':'nem igazolt'}</p><p>${e(x.status||'')} ${e(x.notes||'')}</p><p>${url(x.source)}${x.nov?' · 2026. november 9-i gyűjtés, újbóli forrásellenőrzés szükséges':''}</p></details></article>`).join('')||'<p>A megadott szűrőkkel nincs rögzített csomagár.</p>'}</div><details class="panel"><summary>Nem összehasonlítható vagy hiányzó ajánlatok (${unknown.length})</summary><p>A forrásban elérhető tételek, ahol a csomagár vagy fogásszám nem igazolt.</p>${unknown.map(x=>`<p><b>${e(x.name)}:</b> ${e(x.type)} · ${e(x.notes||'részletek nem igazoltak')} · ${url(x.source)}</p>`).join('')}</details><section class="panel"><h2>Mi férne bele az Elefántnál?</h2><p>Próbáljatok ki egy árat és egy feltételezett ételköltséget. A példa nem a tényleges költségeket mutatja.</p><div class="form"><label>Tervezett ár (Ft)<input id="meet-price" type="number" min="0" value="3500"></label><label>Feltételezett ételköltség (%)<input id="meet-cost" type="number" min="0" max="100" value="35"></label></div><p id="meet-result"></p><p class="muted">Példaértékek. Egységes adózási alapon megadott összegekkel számoljatok; egyéb változó és fix költségek nélkül. Ez nem profit.</p></section><details class="panel"><summary>További menüminták a kutatásból</summary><p>A teljes forrástábla a kutatási háttérből érhető el. A menüminták egyedi fogásokat és csomagokat is tartalmaznak, ezért nem adjuk őket automatikusan ehhez a rangsorhoz.</p>${url('https://docs.google.com/spreadsheets/d/1eigqlKCEuAGTrBA-96k44CB51-EedJh_FJafi2lb_ww/edit')}</details>`}function mount(rerender){let c=document.getElementById('meet-courses');if(!c)return;c.onchange=x=>{courses=x.target.value;rerender()};document.getElementById('meet-channel').onchange=x=>{channel=x.target.value;rerender()};document.getElementById('meet-mode').onchange=x=>{mode=x.target.value;rerender()};document.getElementById('meet-reset').onclick=()=>{courses='2';channel='';mode='listed';rerender()};let calculate=()=>{let p=Number(document.getElementById('meet-price').value),f=Number(document.getElementById('meet-cost').value);document.getElementById('meet-result').textContent=(p>=0&&f>=0&&f<=100)?`Ételköltség utáni egyszerű különbözet: ${money(Math.round(p*(1-f/100)))} / menü`:'Adj meg nem negatív árat és 0–100% közötti ételköltséget.'};document.getElementById('meet-price').oninput=calculate;document.getElementById('meet-cost').oninput=calculate;calculate()}window.meetingViews={overview,lunch,mount}})();
